// Builds the morning digest from the open invoices and the vendor master.
// Demo business date = 2026-10-10 (the date ProcureGuard's policy file uses). In production use new Date().
const AS_OF = new Date('2026-10-10');
const DAY = 86400000;
const invoices = $('Get open invoices').all().map(i => i.json);
const vendors = Object.fromEntries($('Get vendor master').all().map(v => [v.json.vendor_id, v.json]));
const add = (d, n) => new Date(new Date(d).getTime() + n * DAY);
const fmt = d => d.toISOString().slice(0, 10);
const rs = v => 'Rs ' + Number(v).toLocaleString('en-IN');

const msme = [], discount = [], overdue = [], nonPo = [];
for (const inv of invoices) {
  if (['PAID', 'REJECTED'].includes(inv.status)) continue;
  const v = vendors[inv.vendor_id] || {};
  const net = Number((v.payment_terms || '').match(/Net\s*(\d+)/i)?.[1] || 30);
  let due = add(inv.invoice_date, net);
  if (v.msme_udyam_no) {
    const deadline = add(inv.invoice_date, 45);
    if (deadline < due) due = deadline;
    const left = Math.round((deadline - AS_OF) / DAY);
    if (left <= 7) msme.push(`${inv.invoice_id} ${v.name}: ${rs(inv.total_inr)}, MSME deadline ${fmt(deadline)} (${left} days left)`);
  }
  const disc = (v.payment_terms || '').match(/(\d+(?:\.\d+)?)\s*\/\s*(\d+)/);
  if (disc) {
    const until = add(inv.invoice_date, Number(disc[2]));
    const saving = inv.taxable_value_inr * Number(disc[1]) / 100;
    if (until >= AS_OF) discount.push(`${inv.invoice_id} ${v.name}: save ${rs(saving)} if paid by ${fmt(until)}`);
  }
  if (due < AS_OF) overdue.push(`${inv.invoice_id} ${v.name}: ${rs(inv.total_inr)} was due ${fmt(due)}`);
  if (!inv.po_id) nonPo.push(`${inv.invoice_id} ${v.name}: ${rs(inv.total_inr)} has no purchase order`);
}
const section = (title, rows) => `${title} (${rows.length})\n` + (rows.length ? rows.map(r => '- ' + r).join('\n') : '- none');
const body = [
  `ProcureGuard morning digest for ${fmt(AS_OF)}`, '',
  section('MSME payments due within 7 days', msme), '',
  section('Early-payment discounts still open', discount), '',
  section('Overdue invoices', overdue), '',
  section('Invoices without a purchase order', nonPo), '',
  'Ask the ProcureGuard Payment Approval agent to process the MSME items first.',
].join('\n');
return [{ json: { business_date: fmt(AS_OF), msme_due_7d: msme.length, discounts_open: discount.length,
  overdue: overdue.length, non_po: nonPo.length, body,
  subject: `ProcureGuard digest ${fmt(AS_OF)}: ${msme.length} MSME due, ${discount.length} discounts open, ${nonPo.length} non-PO` } }];
